use super::*;

/// 🫴️ Original incoming values and prior slots survive denied normal admission and paged source growth unchanged.
#[test]
fn original_arena_admitted_growth_returns_same_value_and_preserves_slot_addresses(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    use semio_framework_value::{retirement::controlled::ControlledRetirement,retained_clone::RetainedCloneGrant};
    let law:serde_json::Value=serde_json::from_str(include_str!("../../../🕸️topology/🧫️fixtures/🎟️reachability/🔣️.json")).unwrap();let row=&law["arenaGrowth"];
    for copy in law["copyGrants"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap() as usize){
        let(mut store,heap)=observe(||Store::<String,TestId>::new());assert_eq!(heap,(0,0));let(mut born,mut freed,mut reservations)=(0,0,0);let mut pointers:[Option<(TestId,*const String)>;1337]=[None;1337];
        for slot in 0..row["slots"].as_u64().unwrap() as usize{
            let(mut value,heap)=observe(||format!("original-🧱️-{slot}"));born+=heap.0;freed+=heap.1;let original=value.as_ptr();let capacity=value.capacity();
            let denied=RetainedCloneGrant {maximum_items:0,maximum_copy_bytes:copy,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:0};let(result,heap)=observe(||store.insert_reserved(value,denied));let(error,source)=result.unwrap_err();assert_eq!(error.retained_progress(),Default::default());assert_eq!(heap,(0,0));value=source;assert_eq!(value.as_ptr(),original);assert_eq!(value.capacity(),capacity);
            while store.next_insert_capacity_byte_demand(copy).unwrap()!=0{
                let grant=RetainedCloneGrant {maximum_items:row["itemsPerTurn"].as_u64().unwrap() as usize,maximum_copy_bytes:copy,maximum_capacity_bytes:store.next_insert_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:store.next_insert_release_byte_demand().unwrap(),maximum_depth:store.next_insert_depth_demand().unwrap()};
                for denied in [RetainedCloneGrant {maximum_items:0,..grant},RetainedCloneGrant {maximum_capacity_bytes:grant.maximum_capacity_bytes-1,..grant},RetainedCloneGrant {maximum_depth:grant.maximum_depth-1,..grant}]{let(result,heap)=observe(||store.reserve_insert_step(denied));let(error,receipt)=result.unwrap_err();assert_eq!(heap,(0,0));assert_eq!(receipt,Default::default());assert_eq!(error.retained_progress(),receipt);}
                let(result,heap)=observe(||store.reserve_insert_step(grant));let receipt=result.unwrap();assert!(receipt.fits(grant));assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert_eq!(receipt.copied_bytes,row["copyBytesPerTransfer"].as_u64().unwrap() as usize);assert_eq!(receipt.released_bytes,row["releaseBytesPerReserve"].as_u64().unwrap() as usize);born+=heap.0;freed+=heap.1;reservations+=1;for (id,pointer) in pointers[..slot].iter().flatten(){assert_eq!(store.get(*id).unwrap() as *const String,*pointer);}
            }
            let grant=RetainedCloneGrant {maximum_items:row["itemsPerTurn"].as_u64().unwrap() as usize,maximum_copy_bytes:copy,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:store.next_insert_depth_demand().unwrap()};
            let(result,heap)=observe(||store.insert_reserved(value,RetainedCloneGrant {maximum_depth:grant.maximum_depth-1,..grant}));let(_,source)=result.unwrap_err();assert_eq!(heap,(0,0));assert_eq!(source.as_ptr(),original);
            let(result,heap)=observe(||store.insert_reserved(source,grant));let(id,receipt)=result.unwrap();assert_eq!(heap,(0,0));assert!(receipt.fits(grant));assert_eq!(receipt.copied_items,1);assert_eq!(receipt.copied_bytes,0);assert_eq!(store.get(id).unwrap().as_ptr(),original);pointers[slot]=Some((id,store.get(id).unwrap() as *const String));
        }
        let(id,pointer)=pointers[0].unwrap();let depth=store.next_remove_depth_demand(id).unwrap();let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:depth};let((value,receipt),heap)=observe(||store.remove_granted(id,RetainedCloneGrant {maximum_depth:depth-1,..grant}).unwrap());assert!(value.is_none());assert_eq!(receipt,Default::default());assert_eq!(heap,(0,0));assert_eq!(store.get(id).unwrap() as *const String,pointer);
        let((value,receipt),heap)=observe(||store.remove_granted(id,grant).unwrap());assert_eq!(heap,(0,0));assert_eq!(receipt.copied_items,1);let value=value.unwrap();let original=value.as_ptr();let grant=RetainedCloneGrant {maximum_depth:store.next_insert_depth_demand().unwrap(),..grant};let((reused,receipt),heap)=observe(||store.insert_reserved(value,grant).unwrap());assert_eq!(heap,(0,0));assert_eq!(receipt.copied_items,1);assert_eq!(reused.raw_index(),id.raw_index());assert_eq!(store.get(reused).unwrap() as *const String,pointer);assert_eq!(store.get(reused).unwrap().as_ptr(),original);assert!(store.get(id).is_none());
        let(mut owner,heap)=observe(||ControlledRetirement::new(store).unwrap_or_else(|_|panic!("original paged arena requires typed closure")));assert_eq!(heap,(0,0));let mut turns=0;while !owner.terminal_is_empty(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,heap)=observe(||owner.step(grant).unwrap());assert_eq!(step.progress(),owner.step_progress());assert!(step.progress().fits(grant));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<1000000);}assert_eq!(born,freed);let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,row["terminalDropBytes"].as_u64().unwrap() as usize));eprintln!("[DEBUG] Original admitted arena copy={copy} slots=1337 sameIncomingValue=true sameOriginalSlots=true reservations={reservations} physical={freed} turns={turns} terminalDrop=0");
    }
}
